// src/commands/search.js
init_src5();

// src/commands/package-lifecycle.js
function formatPackageLifecycleLines(pkg) {
  const lifecycle = pkg?.lifecycle;
  if (!lifecycle) return [];
  const lines = [`Lifecycle: ${lifecycle.maturity} \xB7 ${lifecycle.support}`];
  const deprecation = lifecycle.deprecation;
  if (!deprecation) return lines;
  lines.push(`Deprecated since ${deprecation.announcedAt}: ${deprecation.message}`);
  if (deprecation.replacementId) {
    lines.push(`Replacement: ${deprecation.replacementId}`);
  }
  if (deprecation.removalAfter) {
    lines.push(`Removal after: ${deprecation.removalAfter}`);
  }
  return lines;
}
function printPackageLifecycle(pkg, indent = "") {
  for (const line of formatPackageLifecycleLines(pkg)) {
    console.log(`${indent}${line}`);
  }
}

// src/commands/search.js
function pluralizeKind(kind) {
  if (!kind) return "packages";
  if (kind === "binary") return "binaries";
  if (kind === "skill") return "skills";
  if (kind === "workflow") return "workflows";
  return `${kind}s`;
}
function headingForKind(kind) {
  if (kind === "binary") return "BINARIES";
  if (kind === "skill") return "SKILLS";
  if (kind === "workflow") return "WORKFLOWS";
  return `${kind.toUpperCase()}S`;
}
function getSearchGuidance(packageKinds) {
  const kinds = new Set(packageKinds);
  const guidance = [];
  if ([...kinds].some((kind) => kind !== "agent")) {
    guidance.push("Install RUDI packages with: rudi install <package-id>");
  }
  if (kinds.has("agent")) {
    guidance.push("Agent Hosts are installed and updated by their vendors.");
    guidance.push("Inspect readiness with: rudi agent hosts --json");
  }
  return guidance;
}
function printSearchGuidance(packageKinds) {
  for (const line of getSearchGuidance(packageKinds)) console.log(line);
}
async function cmdSearch(args, flags) {
  const query = args[0];
  const refreshRegistry = flags.fresh || flags["no-cache"] || false;
  if (refreshRegistry) {
    await fetchIndex({ force: true });
  }
  if (flags.all || flags.a) {
    return listAllPackages(flags);
  }
  if (!query) {
    console.error("Usage: rudi search <query>");
    console.error("       rudi search --all            List all available packages");
    console.error("       rudi search --all -s   List all stacks");
    console.error("       rudi search --all --runtimes List all runtimes");
    console.error("       rudi search --all --binaries List all binaries");
    console.error("       rudi search --all --agents   List all agents");
    console.error("       rudi search --all --workflows List all workflows");
    console.error("Example: rudi search pdf");
    process.exit(1);
  }
  const binariesFlag = flags.binaries || flags.tools;
  const kind = flags.stacks ? "stack" : flags.skills || flags.prompts ? "skill" : flags.workflows ? "workflow" : flags.runtimes ? "runtime" : binariesFlag ? "binary" : flags.agents ? "agent" : null;
  if (flags.prompts && !flags.skills) {
    console.log("Note: --prompts has been renamed to --skills. Use --skills instead.\n");
  }
  console.log(`Searching for "${query}"...`);
  try {
    const results = await searchPackages(query, { kind });
    if (results.length === 0) {
      console.log("No packages found matching your query.");
      return;
    }
    if (flags.json) {
      console.log(JSON.stringify(results, null, 2));
      return;
    }
    console.log(`
Found ${results.length} package(s):
`);
    const grouped = {
      stack: results.filter((r) => r.kind === "stack"),
      skill: results.filter((r) => r.kind === "skill"),
      prompt: results.filter((r) => r.kind === "prompt"),
      workflow: results.filter((r) => r.kind === "workflow"),
      runtime: results.filter((r) => r.kind === "runtime"),
      binary: results.filter((r) => r.kind === "binary"),
      agent: results.filter((r) => r.kind === "agent")
    };
    for (const [kind2, packages] of Object.entries(grouped)) {
      if (packages.length === 0) continue;
      console.log(`${headingForKind(kind2)}:`);
      for (const pkg of packages) {
        const id = pkg.id || `${kind2}:${pkg.name}`;
        console.log(`  ${id}`);
        console.log(`    ${pkg.description || "No description"}`);
        if (pkg.version) {
          console.log(`    v${pkg.version}`);
        }
        printPackageLifecycle(pkg, "    ");
        console.log();
      }
    }
    printSearchGuidance(results.map((result) => result.kind));
  } catch (error) {
    console.error(`Search failed: ${error.message}`);
    process.exit(1);
  }
}
async function listAllPackages(flags) {
  const binariesFlag = flags.binaries || flags.tools;
  const kind = flags.stacks ? "stack" : flags.skills || flags.prompts ? "skill" : flags.workflows ? "workflow" : flags.runtimes ? "runtime" : binariesFlag ? "binary" : flags.agents ? "agent" : null;
  if (flags.prompts && !flags.skills) {
    console.log("Note: --prompts has been renamed to --skills. Use --skills instead.\n");
  }
  try {
    const kinds = kind ? [kind] : ["stack", "skill", "workflow", "runtime", "binary", "agent"];
    const allPackages = {};
    let totalCount = 0;
    for (const k of kinds) {
      const packages = await listPackages(k);
      allPackages[k] = packages;
      totalCount += packages.length;
    }
    if (flags.json) {
      console.log(JSON.stringify(allPackages, null, 2));
      return;
    }
    console.log(kind ? `Listing all ${pluralizeKind(kind)}...` : "Listing all available packages...");
    for (const k of kinds) {
      const packages = allPackages[k];
      if (packages.length === 0) continue;
      console.log(`
${headingForKind(k)} (${packages.length}):`);
      console.log("\u2500".repeat(50));
      for (const pkg of packages) {
        const id = pkg.id || `${k}:${pkg.name}`;
        const runtime = pkg.runtime ? ` [${pkg.runtime.replace("runtime:", "")}]` : "";
        console.log(`  ${id}${runtime}`);
        console.log(`    ${pkg.description || "No description"}`);
        printPackageLifecycle(pkg, "    ");
      }
    }
    console.log(`
Total: ${totalCount} package(s) available`);
    printSearchGuidance(kinds.filter((k) => allPackages[k].length > 0));
  } catch (error) {
    console.error(`Failed to list packages: ${error.message}`);
    process.exit(1);
  }
}

